#!/usr/bin/env python3
"""Check the default selection's generated bytes against pinned upstream files."""
import hashlib
import pathlib
import sys

source, installed = map(pathlib.Path, sys.argv[1:3])
mode = sys.argv[3]
assert mode in ('0', '1'), 'Expected SET_PRERENEWAL=0 or 1'
expected = {}
compatibility_files = 0


def put(path, relative):
    assert path.is_file(), f'Missing upstream file: {path}'
    key = str(relative).lower()
    # Windows xcopy keeps the spelling of the first occurrence.
    spelling = expected[key][0] if key in expected else relative
    expected[key] = (spelling, path)


def layer(root):
    assert root.is_dir(), f'Missing upstream layer: {root}'
    count = 0
    for directory in ('data', 'SystemEN'):
        base = root / directory
        if base.is_dir():
            for path in sorted(base.rglob('*')):
                if path.is_file():
                    put(path, pathlib.Path(directory) / path.relative_to(base))
                    count += 1
    assert count, f'Empty upstream layer: {root}'
    return count


layer(source / 'Translation/Renewal')
if mode == '1':
    layer(source / 'Translation/Pre-Renewal')
# PACKETVER=20211103 selects 2021-10-28 and the preceding applicable overlays.
for date in ('2017-06-14', '2017-12-13', '2018-06-20', '2019-06-05',
             '2020-09-02', '2021-10-28'):
    root = source / 'Translation/Compatibility' / date
    specific = root / ('Pre-Renewal' if mode == '1' else 'Renewal')
    compatibility_files += layer(specific if specific.is_dir() else root)

additions = ['SystemEN/PetEvolution.lub', 'SystemEN/CheckAttendance.lub', 'SystemEN/PrivateAirplane.lub']
additions += ['data/' + name for name in (
    'mp3nametable.txt', 'resnametable.txt', 'num2cardillustnametable.txt',
    'buyingstoreitemlist.txt', 'cardpostfixnametable.txt', 'indoorrswtable.txt')]
lua = 'data/luafiles514/lua files/'
additions += [lua + 'datainfo/' + name + '.lub' for name in (
    'accessoryid', 'accname', 'spriterobeid', 'spriterobename', 'weapontable', 'tb_cashshop_banner', 'npcidentity', 'jobname')]
additions += [lua + name for name in ('stateicon/efstids.lub', 'stateicon/stateiconimginfo.lub',
                                      'worldviewdata/worldviewdata_table.lub', 'ItemDBNameTbl.lub')]
for name in additions:
    put(source / 'Additions' / name, pathlib.Path(name))

actual = {str(p.relative_to(installed)).lower(): p for p in installed.rglob('*') if p.is_file()}
assert len(actual) == sum(1 for p in installed.rglob('*') if p.is_file()), 'Case-colliding output files'
assert actual.keys() == expected.keys(), f'Output file set differs: missing={expected.keys() - actual.keys()}, extra={actual.keys() - expected.keys()}'
for key, (relative, upstream) in expected.items():
    path = actual[key]
    assert path.relative_to(installed) == relative, f'Output spelling mismatch: {relative}'
    assert hashlib.sha256(path.read_bytes()).digest() == hashlib.sha256(upstream.read_bytes()).digest(), f'Checksum mismatch: {relative}'
print(f'PASS mode={mode}, PACKETVER=20211103: {len(expected)} output checksums, '
      f'{compatibility_files} compatibility inputs, {len(additions)} additions including PetEvolution')
